import type { CSSProperties } from "react";
import { media, type MediaSlug } from "@/content/media";

type PhotoProps = {
  /** Slug from src/content/media.ts (generated by `npm run images`). */
  media: MediaSlug;
  /** Optional art-directed variant for small screens (< 768px). */
  mobileMedia?: MediaSlug;
  /** Overrides the default alt text. Pass "" for decorative images. */
  alt?: string;
  /** Responsive sizes hint, e.g. "(min-width: 1024px) 33vw, 100vw". */
  sizes: string;
  /** Above-the-fold images: eager + high fetch priority. */
  priority?: boolean;
  /** Classes for the <img> (use object-cover + size utilities). */
  className?: string;
  /** object-position, e.g. "60% 50%" */
  position?: string;
  style?: CSSProperties;
};

const srcSet = (slug: MediaSlug) =>
  media[slug].widths.map((w) => `/images/opt/${slug}-${w}.webp ${w}w`).join(", ");

const fallbackSrc = (slug: MediaSlug) => {
  const { widths } = media[slug];
  const w = widths.find((x) => x >= 1200) ?? widths[widths.length - 1];
  return `/images/opt/${slug}-${w}.webp`;
};

/**
 * Responsive WebP image from the optimised set in /public/images/opt.
 * Plain <img>/<picture> because the site is a static export with pre-generated variants.
 */
export function Photo({ media: slug, mobileMedia, alt, sizes, priority = false, className, position, style }: PhotoProps) {
  const entry = media[slug];
  const img = (
    // eslint-disable-next-line @next/next/no-img-element -- variants are pre-generated by scripts/optimize-images.mjs
    <img
      src={fallbackSrc(slug)}
      srcSet={srcSet(slug)}
      sizes={sizes}
      width={entry.width}
      height={entry.height}
      alt={alt ?? entry.alt}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      decoding={priority ? "sync" : "async"}
      className={className}
      style={{ backgroundColor: entry.color, objectPosition: position, ...style }}
    />
  );

  if (!mobileMedia) return img;
  return (
    <picture>
      <source media="(max-width: 767px)" srcSet={srcSet(mobileMedia)} sizes="100vw" />
      {img}
    </picture>
  );
}
